{
  "findings": [
    {
      "check_id": "CKV_AWS_79",
      "title": "Instance Metadata Service Version 1 (IMDSv1) is not disabled",
      "resource": "aws_launch_template.web_app",
      "severity": "MEDIUM",
      "explanation": "The launch template does not configure metadata_options to enforce IMDSv2. Leaving IMDSv1 enabled allows SSRF attacks to retrieve temporary credentials from the instance metadata service."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Hardcoded secrets in user_data",
      "resource": "aws_launch_template.web_app",
      "severity": "CRITICAL",
      "explanation": "The API key 'sk-1234567890abcdef' is hardcoded directly in the user_data script. This exposes sensitive credentials in the Terraform state and CloudTrail logs, violating secret management best practices."
    }
  ],
  "patched_code": "resource "aws_launch_template" "web_app" {
  name_prefix   = "automated-employee-onboarding-platform-lt-web-"
  image_id      = data.aws_ami.ubuntu.id
  instance_type = var.instance_type
  key_name      = var.key_pair_name
  vpc_security_group_ids = [aws_security_group.web_app.id]

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  user_data = base64encode(<<-EOF
              export DATABASE_PASSWORD="${var.db_password}"
              # TODO: Retrieve API_KEY securely via AWS Secrets Manager or SSM Parameter Store instead of hardcoding
              apt-get update
              apt-get install -y nginx nodejs npm
              systemctl start nginx
              systemctl enable nginx
              EOF
  )
  tag_specifications {
    resource_type = "instance"
  }
}",
  "fix_summary": "Added metadata_options block to enforce IMDSv2 by setting http_tokens to required. Removed the hardcoded API key from user_data and replaced it with a comment indicating secure retrieval methods, as no specific variable was provided for it in the original file context."
}
